import{_ as t,o as s,c as o,ag as r}from"./chunks/framework.BIas3y6W.js";const u=JSON.parse('{"title":"Project Fair","description":"","frontmatter":{"source":"weeks/16-project-fair/project-fair.md"},"headers":[],"relativePath":"weeks/16-project-fair/project-fair.md","filePath":"weeks/16-project-fair/project-fair.md"}'),a={name:"weeks/16-project-fair/project-fair.md"};function n(i,e,l,d,h,c){return s(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="project-fair" tabindex="-1">Project Fair <a class="header-anchor" href="#project-fair" aria-label="Permalink to &quot;Project Fair&quot;">​</a></h1><blockquote><p>The closing event of the course, in finals week (week 16), in the course&#39;s scheduled <strong>2-hour final exam slot</strong> (University Regulation H-1-b: final sessions follow the approved final exam schedule). A gallery walk (science-fair style), so everyone presents and everyone tries each other&#39;s apps, plus a few spotlight demos and peer voting. The Fair itself takes about 80 minutes of the slot, including set-up; the rest is the post-course self-assessment, the course retrospective and the awards. Written for a class of <strong>5 or more students</strong>. Smaller class? See <a href="#small-classes">Small classes</a>.</p></blockquote><h2 id="the-idea" tabindex="-1">The idea <a class="header-anchor" href="#the-idea" aria-label="Permalink to &quot;The idea&quot;">​</a></h2><p>Not everyone presenting to a silent room. Instead: <strong>half the class presents at stations while the other half walks around and tries their apps, then they swap.</strong> Two rounds means everyone both presents and visits. It&#39;s low-pressure and hands-on, and every project gets real users.</p><p>Your oral walkthrough 3 is already done by now (it was in week 14), so the Fair is about showing your work, not being examined. Your votes and the votes you receive don&#39;t affect anyone&#39;s grade; taking part counts as participation. Can&#39;t come for a reason the University recognizes (Regulations M-1 and M-3)? Tell your instructor as early as you can, and they&#39;ll arrange a make-up (<a href="./../../assessment/#absences-and-make-up-work">Absences and make-up work</a>).</p><h2 id="what-each-presenter-brings" tabindex="-1">What each presenter brings <a class="header-anchor" href="#what-each-presenter-brings" aria-label="Permalink to &quot;What each presenter brings&quot;">​</a></h2><ul><li>The <strong>live app</strong> at its production URL, open on a laptop or phone, ready to hand to a visitor.</li><li>A one-line problem statement you can say in 10 seconds.</li><li>Your <strong>known issues</strong>: your README&#39;s &quot;Known issues and next steps&quot; section open in a tab, or the top one or two on a sticky note.</li><li>Your <strong>demo video</strong> queued as a backup if the live app hiccups.</li><li>A sign or sticky note with the app&#39;s name and its URL or QR code.</li></ul><h2 id="format" tabindex="-1">Format <a class="header-anchor" href="#format" aria-label="Permalink to &quot;Format&quot;">​</a></h2><h3 id="two-rounds-gallery-walk" tabindex="-1">Two rounds (gallery walk) <a class="header-anchor" href="#two-rounds-gallery-walk" aria-label="Permalink to &quot;Two rounds (gallery walk)&quot;">​</a></h3><ul><li><strong>Round A (25 min):</strong> Group 1 stands at their stations; Group 2 visits, tries apps, asks questions, fills in feedback cards and votes.</li><li><strong>Swap (5 min).</strong></li><li><strong>Round B (25 min):</strong> Group 2 presents; Group 1 visits.</li></ul><p>Presenters give a <strong>60–90 second</strong> pitch when a visitor arrives: problem → quick demo → one thing you&#39;re proud of → <strong>one known issue</strong>. Then <strong>hand the app over</strong> and let the visitor try it. With 5–6 students, visitors spend about 8–10 minutes at each station; with 10, about 5.</p><h3 id="spotlight-demos-10-min" tabindex="-1">Spotlight demos (10 min) <a class="header-anchor" href="#spotlight-demos-10-min" aria-label="Permalink to &quot;Spotlight demos (10 min)&quot;">​</a></h3><p>Pick <strong>3</strong> projects (4 if the rounds finished early) to demo to the whole room for about 3 minutes each. Choose a spread: one strong build, one great recovery story, one with a clear known-issues section, one that shows a security feature (such as its RLS policies). Rotate who gets picked across cohorts so it isn&#39;t always the same students. Presenting a spotlight is always optional.</p><h2 id="run-sheet" tabindex="-1">Run sheet <a class="header-anchor" href="#run-sheet" aria-label="Permalink to &quot;Run sheet&quot;">​</a></h2><p>The whole final exam slot, 2 hours. Arrive on time: the slot is fixed by the University&#39;s final exam schedule, so it can&#39;t run over.</p><table tabindex="0"><thead><tr><th>Time</th><th>What</th><th>Who</th></tr></thead><tbody><tr><td>0:00–0:10</td><td>Set up stations; post every URL and QR code in one shared list. Instructor explains the format, hands out feedback cards and voting slips, and splits the class into Group 1 (presents first) and Group 2</td><td>All</td></tr><tr><td>0:10–0:35</td><td><strong>Round A:</strong> Group 1 presents, Group 2 visits and votes</td><td>All</td></tr><tr><td>0:35–0:40</td><td>Swap</td><td>All</td></tr><tr><td>0:40–1:05</td><td><strong>Round B:</strong> Group 2 presents, Group 1 visits and votes</td><td>All</td></tr><tr><td>1:05–1:15</td><td><strong>Spotlight demos</strong> (3 projects, about 3 minutes each)</td><td>Selected</td></tr><tr><td>1:15–1:20</td><td>Presenters read their feedback cards; instructor starts tallying votes</td><td>All</td></tr><tr><td>1:20–1:35</td><td><strong>Post-course self-assessment</strong> on Canvas (🔴 AI off); instructor finishes the tally</td><td>All</td></tr><tr><td>1:35–1:50</td><td><strong>Course retrospective</strong></td><td>All</td></tr><tr><td>1:50–2:00</td><td><strong>Awards and closing</strong></td><td>Instructor</td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>For a class larger than about 16, run three rounds of thirds instead of two halves (about 15 minutes each, with 3-minute swaps, in the same 55 minutes). Keep each presenter&#39;s audience small so apps actually get used.</p></div><h2 id="peer-voting-categories" tabindex="-1">Peer voting categories <a class="header-anchor" href="#peer-voting-categories" aria-label="Permalink to &quot;Peer voting categories&quot;">​</a></h2><p>Give each student a few votes (sticky dots or slips). Vote for projects other than your own. Use <strong>Clearest known issues</strong> plus 3–4 others:</p><ul><li><strong>Clearest known issues</strong>: told me honestly what doesn&#39;t work yet, and what they&#39;d do about it. (Always included: the course gives credit for this.)</li><li><strong>Most useful</strong>: I&#39;d actually use this.</li><li><strong>Best recovery story</strong>: the best &quot;what broke and how I fixed it&quot;.</li><li><strong>Most secure</strong>: clearest access rules; thought hard about safety.</li><li><strong>Best spec</strong>: the app matches a clear, well-written spec.</li><li><strong>Crowd favorite</strong>: overall.</li><li>(Optional) <strong>Most accessible</strong>, <strong>Best README</strong>, <strong>Most surprising</strong>.</li></ul><p>Keep it celebratory, not competitive: everyone who ships gets recognized, and the categories spotlight different strengths so many students win something.</p><h2 id="feedback-cards" tabindex="-1">Feedback cards <a class="header-anchor" href="#feedback-cards" aria-label="Permalink to &quot;Feedback cards&quot;">​</a></h2><p>Print a stack, or use the digital form your instructor shares. Each visitor fills in one card per app they try, 🔴 <strong>AI off</strong>: it&#39;s your own opinion, addressed to a person. Keep it short:</p><ol><li><strong>App:</strong> [app name] · <strong>Visitor:</strong> [first name or GitHub username, optional]</li><li><strong>I tried:</strong> what you did in the app.</li><li><strong>One thing I liked:</strong></li><li><strong>One thing I&#39;d improve:</strong></li><li><strong>Did the presenter tell you one thing that doesn&#39;t work yet?</strong> yes / no</li><li><strong>Did it work from the app alone, with no help?</strong> yes / mostly / no</li></ol><p>Presenters keep their cards. They&#39;re honest user feedback and good material for one last fix and for the final reflection. Don&#39;t photograph or commit them to a repo.</p><h2 id="accessibility-considerations" tabindex="-1">Accessibility considerations <a class="header-anchor" href="#accessibility-considerations" aria-label="Permalink to &quot;Accessibility considerations&quot;">​</a></h2><ul><li><strong>Stations:</strong> leave clear paths for wheelchair and mobility access; don&#39;t cram tables.</li><li><strong>Noise:</strong> a loud room is hard for some people. Offer a quieter corner, and let anyone present their video with headphones instead of a live pitch.</li><li><strong>Presenting is flexible in form:</strong> a student who can&#39;t give a live spoken pitch may play their demo video and answer questions in writing or chat.</li><li><strong>Standing:</strong> provide chairs; nobody has to stand for the whole event.</li><li><strong>Visuals:</strong> ask presenters to zoom their app to a readable size; remind everyone that color-only cues are hard to see.</li><li><strong>Feedback cards:</strong> offer the digital form for anyone who prefers typing or uses a screen reader.</li></ul><p>More on how the course handles timed and spoken activities: <a href="./../../resources/accessibility.html">Accessibility guide</a>.</p><h2 id="onlinehybrid-variant" tabindex="-1">Online/hybrid variant <a class="header-anchor" href="#onlinehybrid-variant" aria-label="Permalink to &quot;Online/hybrid variant&quot;">​</a></h2><p>Run the same shape in a video call:</p><ul><li><strong>Stations = breakout rooms.</strong> Each Group 1 presenter hosts a breakout room with their screen shared; Group 2 members drop into rooms, watch a quick demo, try it from the production URL, and fill in the <strong>digital feedback form</strong>. Swap for Round B.</li><li><strong>Spotlights</strong> happen in the main room with screen sharing.</li><li><strong>Voting</strong> by a poll or a shared form.</li><li>Ask presenters to share the <strong>production URL in chat</strong> so visitors use the app, not just watch.</li><li>Record only with everyone&#39;s consent; cameras stay optional.</li></ul><p>For a <strong>hybrid</strong> room (some in person, some remote), pair each remote presenter with an in-person buddy who carries a laptop to their station, and put all URLs and QR codes in a shared list so both audiences can reach every app.</p><h2 id="small-classes" tabindex="-1">Small classes <a class="header-anchor" href="#small-classes" aria-label="Permalink to &quot;Small classes&quot;">​</a></h2><p>With fewer than 5 students, a gallery walk has too few visitors. Instead, each student gets a <strong>public demo slot</strong> your instructor arranges (a department seminar, a lab meeting, or invited staff), plus <strong>three outside testers</strong> who use the feedback card on made-up data. There&#39;s no voting; the &quot;clearest known issues&quot; credit stays. Details for instructors: Course variants; for students working alone: the <a href="./../../resources/self-paced.html">Self-paced path</a>.</p><h2 id="after-the-fair" tabindex="-1">After the Fair <a class="header-anchor" href="#after-the-fair" aria-label="Permalink to &quot;After the Fair&quot;">​</a></h2><ul><li>Announce the category winners in the closing minutes; thank everyone for shipping.</li><li>Remind students that the <strong>revised AI-use rules and the final reflection</strong> are still due on Canvas by 11:59 pm on the last day of finals week; the product (production URL and screenshot, <code>v1.0</code> release, demo video) was due at the start of the Fair (<a href="./#final-submission">week 16 page</a>).</li><li>Encourage students to keep their repos as a portfolio and to follow the <a href="./#going-further">keep-going roadmap</a>.</li></ul>',36)])])}const g=t(a,[["render",n]]);export{u as __pageData,g as default};
